import os
import re
import subprocess
import sys
from urllib.parse import urlsplit, urlunsplit

PUBLIC_HOSTS = {
    'pypi.org', 'pypi.python.org', 'files.pythonhosted.org', 'pythonhosted.org',
    'test.pypi.org', 'pypi.io',
}

def redact(value, key=''):
    value = str(value)
    upper = key.upper()
    if any(word in upper for word in ('PASSWORD', 'PASSWD', 'TOKEN', 'SECRET', 'CREDENTIAL', 'AUTH')):
        return '<redacted>'
    if '://' in value:
        try:
            parts = urlsplit(value)
            host = parts.hostname or ''
            if parts.port:
                host = f'{host}:{parts.port}'
            netloc = host
            if parts.username is not None or parts.password is not None:
                netloc = '<redacted>@' + host
            return urlunsplit((parts.scheme, netloc, parts.path, parts.query, parts.fragment))
        except Exception:
            return '<redacted-url>'
    return re.sub(r'(?i)(token|password|passwd|secret|api[_-]?key)=(["'^&'"\\s]+)', r'\\1=<redacted>', value)

def nonempty(value):
    if value is None:
        return False
    if isinstance(value, (list, tuple)):
        return any(nonempty(v) for v in value)
    return bool(str(value).strip())

def values_from_pip_config():
    try:
        from pip._internal.configuration import Configuration
        cfg = Configuration(isolated=False)
        cfg.load()
        return dict(cfg.items()), None
    except Exception as exc:
        return {}, type(exc).__name__

def public_source(value):
    try:
        host = (urlsplit(str(value)).hostname or '').lower().rstrip('.')
    except Exception:
        return False
    return host in PUBLIC_HOSTS or host.endswith('.pypi.org') or host.endswith('.pythonhosted.org')

env = {k: v for k, v in os.environ.items() if k.startswith('PIP_')}
config_values, config_error = values_from_pip_config()
print('INDEX_EVALUATION=single-bounded')
print('PIP_CONFIG_LOAD_ERROR=' + (config_error or 'none'))
print('PIP_ENVIRONMENT_REDACTED:')
for key in sorted(env):
    print(f'  {key}={redact(env[key], key)}')
print('PIP_CONFIG_RELEVANT_REDACTED:')
for key in sorted(config_values):
    low = key.lower()
    if any(term in low for term in ('index-url', 'extra-index', 'find-links', 'no-index')):
        print(f'  {key}={redact(config_values[key], key)}')

# PIP_INDEX_URL is the highest-precedence explicit primary. Otherwise use the
# most specific configured install/global index-url value.
primary = env.get('PIP_INDEX_URL', '').strip()
primary_origin = 'env:PIP_INDEX_URL' if primary else ''
if not primary:
    for key in ('install.index-url', 'global.index-url', ':env:.index-url'):
        value = config_values.get(key)
        if nonempty(value):
            primary = str(value).strip()
            primary_origin = 'pip-config:' + key
            break

extra_sources = []
for key, value in env.items():
    if key in {'PIP_EXTRA_INDEX_URL', 'PIP_FIND_LINKS'} and nonempty(value):
        extra_sources.append(key)
for key, value in config_values.items():
    low = key.lower()
    if ('extra-index-url' in low or 'find-links' in low) and nonempty(value):
        extra_sources.append('pip-config:' + key)
extra_sources = sorted(set(extra_sources))

print('EFFECTIVE_PRIMARY=' + (redact(primary, 'INDEX_URL') if primary else '<none>'))
print('EFFECTIVE_PRIMARY_ORIGIN=' + (primary_origin or '<none>'))
print('EXTRA_OR_FALLBACK_SOURCES=' + (','.join(extra_sources) if extra_sources else '<none>'))

if not primary:
    classification = 41
    label = 'BLOCKED_INDEX_NOT_CONFIGURED'
elif public_source(primary):
    classification = 45
    label = 'BLOCKED_INDEX_PUBLIC_PRIMARY'
elif extra_sources:
    classification = 46
    label = 'BLOCKED_INDEX_FALLBACK'
else:
    print('APPROVED_PRIMARY_PROBE=running')
    probe_env = os.environ.copy()
    probe_env['PIP_NO_INPUT'] = '1'
    # Uses pip's already effective configured primary; no public fallback is added.
    probe = subprocess.run(
        [sys.executable, '-m', 'pip', 'index', 'versions', 'nicegui',
         '--disable-pip-version-check', '--no-cache-dir', '--timeout', '15', '--retries', '0'],
        env=probe_env, capture_output=True, text=True, timeout=45,
    )
    combined = (probe.stdout or '') + '\\n' + (probe.stderr or '')
    has_required = bool(re.search(r'(?<"'![0-9])3'"\\.15\\.0(?"'![0-9])'"', combined))
    print(f'APPROVED_PRIMARY_PROBE_RC={probe.returncode}')
    print(f'APPROVED_PRIMARY_PROBE_RESOLVED_NICEGUI_3_15_0={str(has_required).lower()}')
    if probe.returncode == 0 and has_required:
        classification = 0
        label = 'PASS'
    else:
        classification = 47
        label = 'BLOCKED_INDEX_ACCESS'

print(f'PREREQUISITE_CLASSIFICATION={label}')
print(f'PREREQUISITE_CODE={classification}')
raise SystemExit(classification)
